 38	        if self.duration.is_zero() || self.duration > Duration::from_secs(3600) {
 39	            return Err(Error::Invalid("inventory duration budget"));
 40	        }
 41	        Instant::now()
 42	            .checked_add(self.duration)
 43	            .ok_or(Error::Invalid("inventory deadline"))
 44	    }
 45	    fn check(&self, deadline: Instant) -> Result<()> {
 46	        if self.cancelled.load(Ordering::Relaxed) || Instant::now() >= deadline {
 47	            return Err(Error::Invalid("inventory cancelled or timed out"));
 48	        }
 49	        Ok(())
 50	    }
 51	}
