   434	fn request_coordinate(record: &Committed) -> Result<(Cid, usize)> {
   435	    let es: Vec<_> = entries(&record.manifest).collect();
   436	    if es.len() != 1 {
   437	        return Err(corrupt("inventory requires one service request entry"));
   438	    }
   439	    let id = cid(&es[0]["ciphertext"])
   440	        .parse()
   441	        .map_err(|_| corrupt("request CID"))?;
   442	    let length =
   443	        usize::try_from(number(&es[0]["length"])).map_err(|_| corrupt("request length"))?;
