   449	fn payload(
   450	    conn: &Connection,
   451	    id: &Cid,
   452	    expected: usize,
   453	) -> Result<(Availability, Option<Vec<u8>>)> {
   454	    // A WITHOUT ROWID index seek can materialize the entire key record before
   455	    // SQLite's value limit applies. Scan by the bounded CID field instead;
   456	    // per-call VM cancellation bounds checked SQL work. This costs a linear
   457	    // object scan per sample and makes no large-archive latency promise.
   458	    let length: Option<i64> = conn
   459	        .query_row(
   460	            "SELECT length(bytes) FROM objects NOT INDEXED WHERE +cid=?",
   461	            [id.to_string()],
   462	            |r| r.get(0),
   463	        )
   464	        .optional()?;
   465	    let Some(length) = length else {
   466	        return Ok((Availability::Missing, None));
   467	    };
   468	    if length != expected as i64 {
   469	        return Ok((Availability::Corrupt, None));
   470	    }
   471	    let old = conn.set_limit(
   472	        rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH,
   473	        RECOVERY_SQLITE_LENGTH_LIMIT,
   474	    )?;
   475	    let result = conn.query_row(
   476	        "SELECT substr(bytes,1,?2) FROM objects NOT INDEXED WHERE +cid=?1",
   477	        params![id.to_string(), service::MAX_REQUEST as i64],
   478	        |r| r.get::<_, Vec<u8>>(0),
   479	    );
   480	    conn.set_limit(rusqlite::limits::Limit::SQLITE_LIMIT_LENGTH, old)?;
   481	    let bytes = result?;
   482	    if bytes.len() != expected || ciphertext_cid(&bytes) != *id {
   483	        Ok((Availability::Corrupt, None))
   484	    } else {
   485	        Ok((Availability::Available, Some(bytes)))
   486	    }
   487	}
   488	/// No grant is inferred from selection. The service/reader must authorize first.
   489	/// This fresh read never reuses the inventory transaction's old payload snapshot.
   490	pub fn source(
   491	    path: &Path,
   492	    profile: Profile,
   493	    binding: attested::Binding,
   494	    selection: &Selection,
   495	    max_payload_bytes: usize,
   496	    budget: Budget,
   497	) -> Result<Source> {
   498	    if selection.profile != profile || selection.binding != binding {
   499	        return Err(Error::Invalid(
   500	            "source selection differs from owner binding",
   501	        ));
   502	    }
   503	    binding.validate()?;
   504	    let deadline = budget.deadline()?;
   505	    budget.check(deadline)?;
   506	    let reader = RecoveryReader::open_profile_configured(path, profile.number(), |conn| {
   507	        configure_read(conn, &budget, deadline)
   508	    })?;
   509	    let plan = plan(&reader, profile, &binding)?;
   510	    let record = attested::record(&reader.ledger.conn, selection.frontier.through)?;
   511	    let envelope = attested::envelope(&reader.ledger.conn, record.sequence)?;
   512	    if budget.items < 1 || cost(&record, &envelope) > budget.metadata_bytes {
   513	        return Err(Error::Invalid("inventory audit budget exhausted"));
   514	    }
   515	    let verified = proof::verify_at(
   516	        &envelope,
   517	        &binding.context(),
   518	        &record.manifest,
   519	        &record.receipt,
   520	        &selection.frontier,
   521	    )
   522	    .map_err(|_| corrupt("selected proof changed"))?;
   523	    purpose(&record, &verified, plan.as_ref())?;
   524	    let (id, length) = request_coordinate(&record)?;
   525	    if length > max_payload_bytes {
   526	        return Err(Error::Invalid("selected payload exceeds source budget"));
   527	    }
   528	    let (availability, bytes) = payload(&reader.ledger.conn, &id, length)?;
   529	    budget.check(deadline)?;
   530	    let Some(bytes) = bytes else {
   531	        return Ok(Source::Unavailable(availability));
   532	    };
   533	    let signed = service::verify_retained_request(&record, &bytes)
   534	        .map_err(|_| corrupt("selected writer request"))?;
   535	    if signed.request.scope != service::hex(&binding.scope) {
   536	        return Err(corrupt("selected request scope"));
   537	    }
   538	    budget.check(deadline)?;
   539	    Ok(Source::Available {
   540	        bytes,
   541	        writer: signed.request.principal,
   542	    })
   543	}
