   549	    #[test]
   550	    fn sqlite_vm_deadline_and_cancel_interrupt_unyielding_queries() {
   551	        for cancel in [false, true] {
   552	            let conn = Connection::open_in_memory().unwrap();
   553	            let cancelled = Arc::new(AtomicBool::new(false));
   554	            let budget = Budget {
   555	                items: 1,
   556	                metadata_bytes: 1,
   557	                duration: if cancel {
   558	                    Duration::from_secs(60)
   559	                } else {
   560	                    Duration::from_millis(20)
   561	                },
   562	                cancelled: cancelled.clone(),
   563	            };
   564	            configure_read(&conn, &budget, budget.deadline().unwrap()).unwrap();
   565	            let interrupt = conn.get_interrupt_handle();
   566	            let (done, wait) = std::sync::mpsc::channel();
   567	            // Bound a broken callback without counting that watchdog as success.
   568	            let watchdog = std::thread::spawn(move || {
   569	                if wait.recv_timeout(Duration::from_secs(3)).is_err() {
   570	                    interrupt.interrupt();
   571	                    true
   572	                } else {
   573	                    false
   574	                }
   575	            });
   576	            let cancellation = cancel.then(|| {
   577	                std::thread::spawn(move || {
   578	                    std::thread::sleep(Duration::from_millis(20));
   579	                    cancelled.store(true, Ordering::Relaxed);
   580	                })
   581	            });
   582	            let result = conn.query_row("WITH RECURSIVE n(x) AS (VALUES(1) UNION ALL SELECT x+1 FROM n WHERE x<1000000000) SELECT sum(x) FROM n", [], |r| r.get::<_,i64>(0));
   583	            let _ = done.send(());
   584	            let fallback = watchdog.join().unwrap();
   585	            if let Some(thread) = cancellation {
   586	                thread.join().unwrap();
   587	            }
   588	            assert!(
   589	                !fallback,
   590	                "watchdog, not the production VM callback, interrupted SQL"
   591	            );
   592	            assert!(
   593	                matches!(result, Err(rusqlite::Error::SqliteFailure(e,_)) if e.code == rusqlite::ErrorCode::OperationInterrupted)
   594	            );
   595	        }
   596	    }
   597	}
