        .page(
            None,
            PageBudget {
                record_bytes: 1,
                ..page_budget()
            },
            budget()
        )
        .is_err());
    assert!(a
        .page(
            None,
            PageBudget {
                payload_bytes: 1,
                ..page_budget()
            },
            budget()
        )
        .is_err());
    let mut b = budget();
