                .err()
                .unwrap()
                .to_string(),
            expected
        );
    }
    let t = tempfile::tempdir().unwrap();
    let f = fixture(t.path(), Profile::Copied);
    let mut archive = copied::Archive::open(&f.root, f.binding.clone()).unwrap();
