            .env("KAN_INVENTORY_LARGE_SOURCE", f.db())
            .env("KAN_INVENTORY_LARGE_KIND", kind)
            .output()
            .unwrap();
        println!("{kind}: {}", String::from_utf8_lossy(&out.stdout));
        assert!(
            out.status.success(),
            "{}\n{}",
